import{_ as a,a0 as i,w as s,s as l,ao as d,I as r,x as e,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux有問必答：在CentOS或RHEL防火牆上開啓端口 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：在CentOS或RHEL防火牆上開啓端口 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：在CentOS或RHEL防火牆上開啓端口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：在CentOS或RHEL防火牆上開啓端口 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141029 Linux FAQs with Answers--How to open a port in the firewall on CentOS or RHEL","title":"Linux有問必答：在CentOS或RHEL防火牆上開啓端口","tag":"201411","desc":""},"relativePath":"201411/20141029 Linux FAQs with Answers--How to open a port in the firewall on CentOS or RHEL.md","filePath":"[post].md"}'),m={name:"201411/20141029 Linux FAQs with Answers--How to open a port in the firewall on CentOS or RHEL.md"};function f(u,t,c,C,L,h){const n=i("Link");return s(),l("div",null,[t[11]||(t[11]=d(`<h1 id="linux有問必答-在centos或rhel防火牆上開啓端口" tabindex="-1">Linux有問必答：在CentOS或RHEL防火牆上開啓端口 <a class="header-anchor" href="#linux有問必答-在centos或rhel防火牆上開啓端口" aria-label="Permalink to “Linux有問必答：在CentOS或RHEL防火牆上開啓端口”">​</a></h1><blockquote><p><strong>問題</strong>：我在CentOS系統上運行一台網頁或文件服務器，打算遠程訪問服務器。因此，我需要更改防火牆規則以允許訪問系統上的某個TCP端口。那麼，有什麼好方法在CentOS或RHEL系統的防火牆上開啓TCP/UDP端口？</p></blockquote><p>如果希望在服務器上提供服務，諸如CentOS或RHEL的企業級Linux發行版包含內置的強大防火牆，它們默認的防火牆規則十分嚴格。因此，如果你安裝了任何定製的服務（比如web服務器、NFS和Samba），那麼它們的流量很有可能被防火牆規則阻塞。所以需要在防火牆上開啓必要的端口以允許流量通過。</p><p>在CentOS/RHEL 6或更早的版本上，iptables服務允許用户與netfilter內核模組交互來在用户空間中配置防火牆規則。然而，從CentOS/RHEL 7開始，一個叫做firewalld新用户空間接口被引入以取代iptables服務。</p><p>使用這個命令察看當前的防火牆規則：</p><pre><code>$ sudo iptables -L 
</code></pre><p><img src="https://farm6.staticflickr.com/5601/15604533686_a8c0ae7b89_z.jpg" alt=""></p><p>現在，讓我們看看如何在CentOS/RHEL上修改防火牆來開啓一個端口。</p><h3 id="在centos-rhel-7上開啓端口" tabindex="-1">在CentOS/RHEL 7上開啓端口 <a class="header-anchor" href="#在centos-rhel-7上開啓端口" aria-label="Permalink to “在CentOS/RHEL 7上開啓端口”">​</a></h3><p>啓動CentOS/RHEL 7後，防火牆規則設置由firewalld服務進程默認管理。一個叫做firewall-cmd的命令列客户端支持和這個守護進程通信以永久修改防火牆規則。</p><p>使用這些命令來永久打開一個新端口（如TCP/80）。</p><pre><code>$ sudo firewall-cmd --zone=public --add-port=80/tcp --permanent
$ sudo firewall-cmd --reload 
</code></pre><p>如果不使用“--permanent”標記，把麼防火牆規則在重啓後會失效。</p><h3 id="在centos-rhel-6上開啓端口" tabindex="-1">在CentOS/RHEL 6上開啓端口 <a class="header-anchor" href="#在centos-rhel-6上開啓端口" aria-label="Permalink to “在CentOS/RHEL 6上開啓端口”">​</a></h3><p>在CentOS/RHEL 6甚至更早版本系統上，iptables服務負責維護防火牆規則。</p><p>使用iptables的第一條命令可以通過防火牆開啓一個新TCP/UDP端口。為了永久保存修改過的規則，還需要第二條命令。</p><pre><code>$ sudo iptables -I INPUT -p tcp -m tcp --dport 80 -j ACCEPT
$ sudo service iptables save 
</code></pre><p>另一種方法是通過一個名為system-config-firewall-tui的命令列用户接口（TUI）的防火牆客户端。</p><pre><code>$ sudo system-config-firewall-tui
</code></pre><p>選擇位於中間的“Customize”按鈕，按下ENTER鍵即可。</p><p><img src="https://farm6.staticflickr.com/5602/15628237745_4409cff52f_z.jpg" alt=""></p><p>如果想要為任何已知的服務（如web服務器）修改防火牆，只需勾選該服務，然後關閉工具。如果想要開啓任意一個TCP/UDP端口，選擇“Forward”按鈕，然後進入下一個界面。</p><p><img src="https://farm4.staticflickr.com/3941/15604533696_12857827ea_z.jpg" alt=""></p><p>選擇“Add”按鈕添加一條新規則。</p><p><img src="https://farm4.staticflickr.com/3941/15008065383_4b92cbd843_z.jpg" alt=""></p><p>指定一個端口（如80）或者端口範圍（如3000-3030）和協議（如tcp或udp）。</p><p><img src="https://farm4.staticflickr.com/3946/15007474154_bef75d8c72_z.jpg" alt=""></p><p>最後，保存修改過的配置，關閉工具。這樣，防火牆就永久保存了。</p><p><img src="https://farm4.staticflickr.com/3942/15628237765_0299a638ab_z.jpg" alt=""></p><hr>`,30)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://ask.xmodulo.com/open-port-firewall-centos-rhel.html"},{default:p(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/open-port-firewall-centos-rhel.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(n,{href:"https://github.com/KayGuoWhu"},{default:p(()=>[...t[2]||(t[2]=[e("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const T=a(m,[["render",f]]);export{x as __pageData,T as default};
